{"cards": [{"node_code": "N_de62003d97ec9bf0", "definition": "研究硅橡胶、环氧树脂等弹性体及热固性聚合物在电气绝缘中的应用，涵盖材料配方、成型工艺、介电性能及聚合物绝缘子结构设计。", "boundary": "本节点聚焦于固态弹性体与热固性聚合物绝缘材料。边界包括：1. 硅橡胶及弹性体绝缘材料；2. 聚合物绝缘子（复合绝缘子）；3. 环氧树脂等热固性树脂的绝缘应用。若侧重液态绝缘漆或灌封胶，归入兄弟节点；若侧重高压击穿机理，归入高电压技术。", "includes": ["硅橡胶及弹性体绝缘材料的配方、性能与制备", "聚合物绝缘子（复合绝缘子）的结构设计与材料特性", "环氧树脂等热固性聚合物在电气绝缘中的应用"], "excludes": ["绝缘漆、灌封胶等液态绝缘介质的研究（归入绝缘漆与树脂及灌封胶）", "绝缘薄膜、塑料薄膜等片状绝缘材料（归入绝缘薄膜与塑料薄膜）", "绝缘介质在高压电场下的局部放电、击穿机理（归入高电压与绝缘技术）"], "sibling_distinctions": [{"other_code": "N_efb2d6f78db9b1dd", "rule": "本节点侧重固态弹性体（如硅橡胶）及热固性聚合物绝缘子；兄弟节点侧重液态绝缘漆、树脂及灌封胶。"}, {"other_code": "N_11732175c81a2cc4", "rule": "本节点侧重块状或成型绝缘材料（如绝缘子）；兄弟节点侧重片状薄膜绝缘材料。"}, {"other_code": "N_6c6bf00c34ca6e5a", "rule": "本节点侧重聚合物整体成型绝缘；兄弟节点侧重纤维纸基浸渍及层压结构绝缘。"}], "cross_boundary_rule": "涉及聚合物绝缘时，若为弹性体或成型绝缘子归入本节点；若为液态浸渍或灌封归入绝缘漆与树脂及灌封胶；若为薄膜归入绝缘薄膜与塑料薄膜。"}, {"node_code": "N_efb2d6f78db9b1dd", "definition": "研究绝缘漆、绝缘树脂及灌封胶等液态或半固态有机绝缘材料的成分、固化机理、介电性能及其在电气系统中的浸渍与封装应用。", "boundary": "本节点聚焦于液态及可固化绝缘材料。边界包括：1. 绝缘漆（浸渍漆、覆盖漆）；2. 绝缘树脂（环氧、聚酯等液态树脂）；3. 灌封胶（用于电子电气封装）。若侧重固态弹性体或成型绝缘子，归入硅橡胶节点；若侧重薄膜，归入薄膜节点。", "includes": ["绝缘漆（浸渍漆、覆盖漆）的成分、性能与制备", "绝缘树脂（液态）及灌封胶的固化机理与介电特性", "液态绝缘材料在电机绕组及电子器件中的浸渍与封装应用"], "excludes": ["硅橡胶、聚合物绝缘子等固态弹性体绝缘材料（归入硅橡胶与聚合物绝缘子）", "绝缘薄膜、塑料薄膜等片状绝缘材料（归入绝缘薄膜与塑料薄膜）", "绝缘介质在高压电场下的局部放电、击穿机理（归入高电压与绝缘技术）"], "sibling_distinctions": [{"other_code": "N_de62003d97ec9bf0", "rule": "本节点侧重液态或可固化绝缘材料（漆、树脂、胶）；兄弟节点侧重固态弹性体及成型绝缘子。"}, {"other_code": "N_11732175c81a2cc4", "rule": "本节点侧重液态浸渍或灌封材料；兄弟节点侧重固态片状薄膜材料。"}, {"other_code": "N_6c6bf00c34ca6e5a", "rule": "本节点侧重液态树脂浸渍；兄弟节点侧重纤维纸基浸渍后的层压结构。"}], "cross_boundary_rule": "涉及树脂或漆时，若侧重液态应用、浸渍或灌封归入本节点；若侧重固化后的固态弹性体或绝缘子结构归入硅橡胶与聚合物绝缘子。"}, {"node_code": "N_11732175c81a2cc4", "definition": "研究聚酯、聚酰亚胺、聚丙烯等塑料薄膜及复合薄膜的介电性能、制备工艺及其在电容器、电缆及电机绝缘中的应用。", "boundary": "本节点聚焦于片状薄膜绝缘材料。边界包括：1. 塑料薄膜（聚酯、聚酰亚胺、聚丙烯等）；2. 复合薄膜（金属化薄膜等）；3. 薄膜在电容器及电缆中的绝缘应用。若侧重块状成型绝缘，归入硅橡胶节点；若侧重纸基层压，归入层压板节点。", "includes": ["聚酯、聚酰亚胺、聚丙烯等塑料薄膜的介电性能与制备", "金属化薄膜、复合薄膜及薄膜电容器的材料基础", "薄膜在电缆绝缘、电机槽绝缘中的应用特性"], "excludes": ["硅橡胶、聚合物绝缘子等块状或弹性体绝缘材料（归入硅橡胶与聚合物绝缘子）", "绝缘漆、灌封胶等液态绝缘材料（归入绝缘漆与树脂及灌封胶）", "绝缘浸渍纸、层压板等纤维基绝缘材料（归入绝缘浸渍纸与层压板）"], "sibling_distinctions": [{"other_code": "N_de62003d97ec9bf0", "rule": "本节点侧重片状薄膜绝缘；兄弟节点侧重块状或成型绝缘子。"}, {"other_code": "N_efb2d6f78db9b1dd", "rule": "本节点侧重固态片状薄膜；兄弟节点侧重液态浸渍或灌封材料。"}, {"other_code": "N_6c6bf00c34ca6e5a", "rule": "本节点侧重塑料薄膜；兄弟节点侧重纤维纸基浸渍及层压结构。"}], "cross_boundary_rule": "涉及薄膜绝缘时，若为塑料或复合薄膜归入本节点；若为纸基薄膜或层压结构归入绝缘浸渍纸与层压板。"}]}
